UPDATE MARKETING_ASSET_PROJECT_APPLY SET status='IN_APPROVAL',business_key=#{businessKey},process_instance_id=#{processInstanceId},
  submitted_time=#{updatedTime},updated_by=#{updatedBy},updated_time=#{updatedTime},lock_version=lock_version+1
WHERE id=#{id} AND status='DRAFT' AND record_status='ACTIVE' AND lock_version=#{expectedVersion}

