SELECT COUNT(*) FROM MARKETING_ASSET_PROJECT_APPLY
WHERE applicant_emp_id=#{empId} AND status='COMPLETED' AND record_status='ACTIVE'
  AND completed_time BETWEEN #{startTime} AND #{endTime}

SELECT COALESCE(SUM(credit_amount),0) FROM MARKETING_ASSET_PROJECT_APPLY
WHERE applicant_emp_id=#{empId} AND status='COMPLETED' AND record_status='ACTIVE'
  AND completed_time BETWEEN #{startTime} AND #{endTime}
